using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using MapSharedProps;using MapSharedProps.EditorTools;
public static class ChestPresentationChecks {
 [Serializable]class Result{public bool pass;public string error;public List<string> checks=new List<string>();}
 public static void Run(){var args=Environment.GetCommandLineArgs();string source=args[Array.IndexOf(args,"-props-export")+1],output=args[Array.IndexOf(args,"-props-output")+1];Directory.CreateDirectory(output);var result=new Result();int code=0;try{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UnityEngine.Rendering.Universal.UniversalRendererData>();var rp=UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset.Create(rd);GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Proof sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;floor.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit"));floor.GetComponent<Renderer>().sharedMaterial.SetColor("_BaseColor",new Color(.22f,.17f,.11f));var camera=new GameObject("Proof camera").AddComponent<Camera>();camera.gameObject.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.aspect=1.28f;camera.backgroundColor=Color.black;camera.clearFlags=CameraClearFlags.SolidColor;camera.targetTexture=new RenderTexture(1280,1000,24,RenderTextureFormat.ARGB32);var data=SmallPropsV1.Read(Path.Combine(source,"small_props.json"));var built=MapSharedPropsBuilder.Build(source);VerifyAndRender(data,built,source,output,camera,sun,(name,pass,detail)=>{if(!pass)throw new Exception(name+": "+detail);result.checks.Add(name);});result.pass=true;AssetDatabase.SaveAssets();}catch(Exception e){result.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"presentation-report.json"),JsonUtility.ToJson(result,true));EditorApplication.Exit(code);}}
 [Serializable]class PlacementCost{public int placements,renderers,uniqueMeshes,effects;public float cameraRenderMedianMs,cameraRenderMaxMs;}
 [Serializable]class PlacementCosts{public List<PlacementCost> rows=new List<PlacementCost>();}
 [Serializable]class Cost{public int ornamentTriangles,fxTriangles,ornamentVertices,fxVertices,uniqueMeshes,uniqueMaterials,slots;public long meshBytes;}
 public static void VerifyAndRender(SmallPropsV1.Data data,MapSharedPropsBuilder.Result built,string source,string output,Camera camera,Light sun,Action<string,bool,string> verify){
  verify("presentation has exactly three ornament IDs and two bounded FX IDs",data.chestOrnamentsV1?.Length==3&&data.chestEffectsV1?.Length==2,"");
  var priorType=typeof(ChestPresentationChecks).Assembly.GetType("MapSharedProps.EditorTools.PreChestPresentationSmallPropsV1");var prior=priorType.GetMethod("Read").Invoke(null,new object[]{Path.Combine(source,"small_props.json")});verify("unchanged previous 43 reader ignores presentation fields",((Array)prior.GetType().GetField("assets").GetValue(prior)).Length==43,"");
  var folder=AssetDatabase.GenerateUniqueAssetPath("Assets/PrePresentationProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));var priorRoot=new GameObject("Previous43Reader");var prefabs=new Dictionary<string,GameObject>();int placed=(int)priorType.GetMethod("Build").Invoke(null,new object[]{source,folder,priorRoot.transform,Shader.Find("MapSharedProps/Lit"),prefabs});verify("previous reader builds all 43 unchanged roots",prefabs.Count==43&&placed==Array.FindAll(File.ReadAllLines(Path.Combine(source,"props.csv")),line=>{var fields=line.Split(',');return fields.Length==11&&prefabs.ContainsKey(fields[1]);}).Length,"");priorRoot.SetActive(false);
  foreach(var a in data.assets){var now=built.prefabs[a.id];var old=prefabs[a.id];var nc=now.GetComponent<MeshCollider>();var oc=old.GetComponent<MeshCollider>();bool sameCollider=(!nc&&!oc)||(nc&&oc&&nc.sharedMesh==oc.sharedMesh);verify(a.id+" exact old root render and collision mesh cache references",now.GetComponent<MeshFilter>().sharedMesh==old.GetComponent<MeshFilter>().sharedMesh&&sameCollider,"");}
  var cost=new Cost();var meshes=new HashSet<Mesh>();var materials=new HashSet<Material>();
  foreach(var id in new[]{"treasurechest_silver","treasurechest_gold","treasurechest_rainbow"}){var prefab=built.prefabs[id];var renderers=prefab.GetComponentsInChildren<MeshRenderer>();bool fx=id!="treasurechest_silver";verify(id+" exact child count; no extra colliders or lights",renderers.Length==(fx?3:2)&&prefab.GetComponentsInChildren<Collider>().Length==1&&prefab.GetComponentsInChildren<Light>().Length==0,"");foreach(var r in renderers){if(r.transform==prefab.transform)continue;var m=r.GetComponent<MeshFilter>().sharedMesh;meshes.Add(m);materials.Add(r.sharedMaterial);verify(id+" child material compiled",r.sharedMaterial.shader.isSupported&&!ShaderUtil.ShaderHasError(r.sharedMaterial.shader),r.sharedMaterial.shader.name);if(r.name=="Side relief"){cost.ornamentTriangles+=m.triangles.Length/3;cost.ornamentVertices+=m.vertexCount;var finish=new List<Vector2>();m.GetUVs(3,finish);verify(id+" finish attribute and shadow ownership",finish.Count==m.vertexCount&&r.shadowCastingMode==ShadowCastingMode.On&&r.sharedMaterial.IsKeywordEnabled("CHEST_ORNAMENT"),"");}else{cost.fxTriangles+=m.triangles.Length/3;cost.fxVertices+=m.vertexCount;cost.slots+=m.vertexCount/4;verify(id+" effect bounded additive instanced no caster",m.vertexCount==(id=="treasurechest_gold"?24:64)&&r.sharedMaterial.renderQueue>=3000&&r.sharedMaterial.enableInstancing&&r.shadowCastingMode==ShadowCastingMode.Off,"");}}
   var probe=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var owned=probe.GetComponentsInChildren<Renderer>();UnityEngine.Object.DestroyImmediate(probe);verify(id+" destroying prefab owns all effect renderers",Array.TrueForAll(owned,r=>r==null),"");}
  foreach(var m in meshes)cost.meshBytes+=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m);cost.uniqueMeshes=meshes.Count;cost.uniqueMaterials=materials.Count;File.WriteAllText(Path.Combine(output,"presentation-cost.json"),JsonUtility.ToJson(cost,true));
  verify("seed agrees with Web FNV UTF16 low16",Mathf.Abs(ChestPresentation.Seed("review-treasurechest_gold-0")-0.00555419921875f)<.0000001f,"computed="+ChestPresentation.Seed("review-treasurechest_gold-0"));
  var raw=File.ReadAllText(Path.Combine(source,"small_props.json"));foreach(var pair in new[]{new[]{"\"chestOrnamentsV1\":","ornament"},new[]{"\"chestEffectsV1\":","effect"}}){int i=raw.IndexOf(pair[0]);if(i<0)throw new Exception("Missing test field");string prefix=raw.Substring(0,i),tail=raw.Substring(i);int at=tail.IndexOf("\"id\":\"treasurechest_");int end=tail.IndexOf('"',at+6);var bad=Path.Combine(output,"invalid-presentation.json");File.WriteAllText(bad,prefix+tail.Substring(0,at)+"\"id\":\"oak\""+tail.Substring(end+1));bool rejected=false;try{SmallPropsV1.Read(bad);}catch(InvalidDataException){rejected=true;}verify(pair[1]+" rejects foreign IDs",rejected,"");File.Delete(bad);}
  foreach(Transform child in built.root.transform)child.gameObject.SetActive(false);float intensity=sun.intensity;var ambient=RenderSettings.ambientLight;var rt=camera.targetTexture;camera.nearClipPlane=.02f;
  void Capture(string name){for(int captureWarm=0;captureWarm<3;captureWarm++)camera.Render();var oldRt=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);png.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),png.EncodeToPNG());UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=oldRt;}
  foreach(var light in new[]{"day","dark"}){float power=light=="day"?1:.06f;sun.intensity=intensity*power;RenderSettings.ambientLight=ambient*power;foreach(var id in new[]{"treasurechest_silver","treasurechest_gold","treasurechest_rainbow"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);foreach(var r in o.GetComponentsInChildren<Renderer>())if(r.sharedMaterial.HasProperty("_ChestTime"))r.sharedMaterial.SetFloat("_ChestTime",0);var effect=o.GetComponent<ChestPresentation>();if(effect){effect.SetSeed("review-"+id+"-0");effect.SetTime(0);}foreach(var angle in new[]{"near","angled"}){camera.transform.position=angle=="near"?new Vector3(1.32f,1.09f,-1.76f):new Vector3(1.55f,3.3f,-2.1f);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,.33f,0)-camera.transform.position);Capture(id+"-presentation-"+light+"-"+angle);}if(effect){effect.SetTime(1);Capture(id+"-presentation-"+light+"-time1");}UnityEngine.Object.DestroyImmediate(o);}}
  sun.intensity=intensity;RenderSettings.ambientLight=ambient;
  // Stress CPU dynamic batching in this proof pipeline only. The procedural shader opts out locally.
  var proofPipeline=GraphicsSettings.currentRenderPipeline as UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset;bool priorBatching=proofPipeline.supportsDynamicBatching;proofPipeline.supportsDynamicBatching=true;
  // The FX shader reconstructs local positions from UV slots, so CPU dynamic batching must not bake only POSITION.
  var floorObject=GameObject.Find("Plane");var floorRenderer=floorObject?floorObject.GetComponent<Renderer>():null;if(floorRenderer)floorRenderer.enabled=false;
  foreach(var id in new[]{"treasurechest_gold","treasurechest_rainbow","mixed"}){var probes=new List<GameObject>();var projected=new List<Rect>();camera.transform.position=new Vector3(0,2.8f,-8);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,.4f,0)-camera.transform.position);foreach(float x in new[]{-2.2f,2.2f}){string selected=id=="mixed"?(x<0?"treasurechest_gold":"treasurechest_rainbow"):id;var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[selected]);o.transform.position=new Vector3(x,0,0);probes.Add(o);var effect=o.GetComponent<ChestPresentation>();effect.SetSeed("position-"+id+"-"+x);effect.SetTime(0);foreach(var r in o.GetComponentsInChildren<Renderer>())r.enabled=r.sharedMaterial.shader.name=="MapSharedProps/ChestFx";var b=o.GetComponentInChildren<ChestPresentation>().transform.Find("Bounded seam light and motes").GetComponent<Renderer>().bounds;float minX=100000,minY=100000,maxX=-100000,maxY=-100000;foreach(int sx in new[]{-1,1})foreach(int sy in new[]{-1,1})foreach(int sz in new[]{-1,1}){var point=camera.WorldToScreenPoint(b.center+Vector3.Scale(b.extents,new Vector3(sx,sy,sz)));minX=Mathf.Min(minX,point.x);minY=Mathf.Min(minY,point.y);maxX=Mathf.Max(maxX,point.x);maxY=Mathf.Max(maxY,point.y);}projected.Add(Rect.MinMaxRect(minX-2,minY-2,maxX+2,maxY+2));}Capture(id+"-two-offset-effects-only");var previous=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);png.Apply();int bright=0,outside=0;var regionHits=new int[projected.Count];var pixels=png.GetPixels32();for(int y=0;y<rt.height;y++)for(int x=0;x<rt.width;x++){var c=pixels[y*rt.width+x];if(Mathf.Max(c.r,c.g,c.b)<8)continue;bright++;bool found=false;for(int region=0;region<projected.Count;region++)if(projected[region].Contains(new Vector2(x,y))){regionHits[region]++;found=true;}if(!found)outside++;}UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=previous;foreach(var o in probes)UnityEngine.Object.DestroyImmediate(o);verify(id+" two translated effects stay within their own projected root bounds",bright>20&&outside<=bright*.02f+2&&Array.TrueForAll(regionHits,n=>n>10),"bright="+bright+", outside="+outside+", per region="+string.Join(",",regionHits));}
  proofPipeline.supportsDynamicBatching=priorBatching;if(floorRenderer)floorRenderer.enabled=true;
  var placementCosts=new PlacementCosts();foreach(int count in new[]{3,30,99}){var mass=new GameObject("Presentation placement cost");for(int k=0;k<count;k++){string id=new[]{"treasurechest_silver","treasurechest_gold","treasurechest_rainbow"}[k%3];var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id],mass.transform);o.transform.position=new Vector3(((k%10)-4.5f)*1.6f,0,(k/10)*1.6f);var effect=o.GetComponent<ChestPresentation>();if(effect){effect.SetSeed("cost-"+k);effect.SetTime(0);}}camera.farClipPlane=200;camera.transform.position=new Vector3(0,21,-13);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,0,6)-camera.transform.position);for(int k=0;k<4;k++)for(int captureWarm=0;captureWarm<3;captureWarm++)camera.Render();var times=new List<float>();var watch=new System.Diagnostics.Stopwatch();for(int k=0;k<15;k++){watch.Restart();for(int captureWarm=0;captureWarm<3;captureWarm++)camera.Render();watch.Stop();times.Add((float)watch.Elapsed.TotalMilliseconds);}times.Sort();var unique=new HashSet<Mesh>();foreach(var f in mass.GetComponentsInChildren<MeshFilter>())unique.Add(f.sharedMesh);placementCosts.rows.Add(new PlacementCost{placements=count,renderers=mass.GetComponentsInChildren<Renderer>().Length,uniqueMeshes=unique.Count,effects=mass.GetComponentsInChildren<ChestPresentation>().Length,cameraRenderMedianMs=times[7],cameraRenderMaxMs=times[14]});verify(count+" placements reuse eight source meshes and bounded effects",unique.Count==8&&mass.GetComponentsInChildren<ChestPresentation>().Length==count*2/3,"");UnityEngine.Object.DestroyImmediate(mass);}File.WriteAllText(Path.Combine(output,"presentation-placement-cost.json"),JsonUtility.ToJson(placementCosts,true));
  var lineup=new GameObject("Upper three presentation lineup");int index=0;foreach(var id in new[]{"treasurechest_silver","treasurechest_gold","treasurechest_rainbow"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id],lineup.transform);o.transform.position=new Vector3((index++-1)*1.6f,0,0);var effect=o.GetComponent<ChestPresentation>();if(effect){effect.SetSeed("review-"+id+"-0");effect.SetTime(0);}}camera.transform.position=new Vector3(2,4.1f,-6);camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,.3f,0)-camera.transform.position);Capture("presentation-upper-lineup");UnityEngine.Object.DestroyImmediate(lineup);
 }
